"""Monthly salaries for the cleaning service.

Data-cleaning rules (derived from inspecting the dataset):
- Billing periods start on the first occurrence, in each month, of the weekday of
  the earliest timesheet record (2025-03-04 -> Tuesday). Records dated before
  that day belong to the previous month's period. This matches the
  `salary_amount` column, a running total of hours * rate that resets on the
  first Tuesday of every month.
- Rows with impossible dates (e.g. 2025-04-31, 2025-06-31) are excluded; they
  are not part of the cumulative `salary_amount` chain.
- Rows whose employee_id is not a known employee are excluded (those IDs fail
  the PESEL checksum and are shadow copies of real employees' records with
  altered tasks and a never-resetting running total).
- Exact duplicate rows (identical apart from `id`) are counted once.
- Malformed `performed_tasks` lists (missing brackets) are parsed leniently.
- Bonuses are recomputed from tasks.csv; task IDs that do not exist there are
  ignored (the provided `bonus` column is inflated by them and contains
  negative values for rows without tasks).
"""
import csv
import re
from collections import defaultdict
from datetime import date, datetime, timedelta
from decimal import ROUND_HALF_UP, Decimal

DATASET = "/app/dataset"


def _pesel_valid(pesel: str) -> bool:
    if not re.fullmatch(r"\d{11}", pesel):
        return False
    weights = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3]
    s = sum(int(d) * w for d, w in zip(pesel[:10], weights))
    return (10 - s % 10) % 10 == int(pesel[10])


def _parse_date(s: str):
    try:
        return datetime.strptime(s.strip(), "%Y-%m-%d").date()
    except ValueError:
        return None


def _first_weekday(year: int, month: int, weekday: int) -> date:
    d = date(year, month, 1)
    return d + timedelta(days=(weekday - d.weekday()) % 7)


def _billing_month(d: date, weekday: int) -> tuple[int, int]:
    start = _first_weekday(d.year, d.month, weekday)
    if d >= start:
        return d.year, d.month
    prev = d.replace(day=1) - timedelta(days=1)
    return prev.year, prev.month


def answer() -> dict[str, list[int]]:
    with open(f"{DATASET}/employees.csv", newline="", encoding="utf-8") as f:
        rates = {
            r["PESEL"].strip(): Decimal(r["hourly_rate"])
            for r in csv.DictReader(f)
            if _pesel_valid(r["PESEL"].strip())
        }

    with open(f"{DATASET}/tasks.csv", newline="", encoding="utf-8") as f:
        task_pay = {
            int(r["task_id"]): Decimal(r["pay_per_completion"])
            for r in csv.DictReader(f)
        }

    with open(f"{DATASET}/timesheet.csv", newline="", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))

    valid_dates = [d for d in (_parse_date(r["date"]) for r in rows) if d]
    anchor_weekday = min(valid_dates).weekday()

    seen = set()
    totals = defaultdict(lambda: defaultdict(Decimal))
    for r in rows:
        d = _parse_date(r["date"])
        pesel = r["employee_id"].strip()
        if d is None or pesel not in rates:
            continue
        key = tuple(v.strip() for k, v in r.items() if k != "id")
        if key in seen:
            continue
        seen.add(key)

        hours = Decimal(r["hours_worked"])
        if hours < 0 or hours > 24:
            continue
        tasks = {int(x) for x in re.findall(r"\d+", r["performed_tasks"])}
        bonus = sum((task_pay[t] for t in tasks if t in task_pay), Decimal(0))

        month = _billing_month(d, anchor_weekday)
        totals[pesel][month] += hours * rates[pesel] + bonus

    return {
        pesel: [
            int(months[m].quantize(Decimal(1), rounding=ROUND_HALF_UP))
            for m in sorted(months)
        ]
        for pesel, months in totals.items()
    }


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

